int nombreVoitures() { return (int)(sizeof(PLACES) / sizeof(PLACES[0])); }
const PlacesVoiture& voiture(int i) { return PLACES[i]; }
const PlacesVoiture* places(const char* id) {
    if (!id) return nullptr;
    for (const PlacesVoiture& p : PLACES) if (std::strcmp(p.id, id) == 0) return &p;
    return nullptr;
}

